<template>
  <section class="match-stage">
    <header class="match-header">
      <div>
        <p class="section-kicker">Standard Clause Match</p>
        <h2>标准条款匹配</h2>
        <p>以项目标准合同条款库为基线，核对当前合同的常见条款要素、内容完整性与待补充事项；默认本地匹配并由 Qwen 复核。</p>
      </div>
      <div class="match-actions">
        <label class="cloud-toggle" :class="{ disabled: isMatching }">
          <input v-model="allowCloudReview" type="checkbox" :disabled="isMatching || !canAnalyze" aria-describedby="match-cloud-notice" />
          <span class="toggle-track" aria-hidden="true"><span></span></span>
          <span><strong>DeepSeek 云端复核</strong><small>勾选后，本次合同文本将发送至 DeepSeek。</small></span>
        </label>
        <button class="match-start" type="button" :disabled="isMatching || !canAnalyze" :title="!canAnalyze ? '请先成功解析合同' : isMatching ? '禁用' : '开始标准条款匹配'" @click="runMatch"><component :is="isMatching ? CircleSlash : ScanSearch" :size="18" />{{ isMatching ? '匹配进行中' : '开始匹配' }}</button>
        <button class="match-export" type="button" :disabled="!match || isExporting" :title="!match || isExporting ? '禁用' : '导出匹配报告'" @click="exportReport"><component :is="!match || isExporting ? CircleSlash : Download" :size="18" />导出匹配报告</button>
      </div>
    </header>
    <p class="match-target-file"><FileText :size="17" /><span>当前匹配文件</span><strong :title="contract.sourceFile || '未命名合同'">{{ contract.sourceFile || '未命名合同' }}</strong></p>
    <section class="match-summary" aria-label="标准条款匹配概览">
      <article><span>完整性评价</span><strong>{{ match?.summary?.overall || '待匹配' }}</strong><small>{{ match ? `${match.summary.completenessScore} / 100` : '等待条款库匹配' }}</small></article><article class="complete"><span>完整</span><strong>{{ match?.summary?.complete || 0 }}</strong><small>已识别主要要素</small></article><article class="partial"><span>部分具备</span><strong>{{ match?.summary?.partial || 0 }}</strong><small>建议补足要素</small></article><article class="missing"><span>缺失</span><strong>{{ match?.summary?.missing || 0 }}</strong><small>优先完善</small></article>
    </section>
    <section class="match-workspace">
      <article class="match-results">
        <div class="match-toolbar"><div><p class="section-kicker">Match Result</p><h3>完整性核对与完善建议</h3></div><div class="match-filter"><select v-model="statusFilter" aria-label="按匹配状态筛选"><option value="全部">全部状态</option><option value="完整">完整</option><option value="部分具备">部分具备</option><option value="缺失">缺失</option></select><input v-model.trim="keyword" type="search" placeholder="筛选条款" aria-label="筛选条款" /></div></div>
        <p id="match-cloud-notice" class="match-cloud-notice">标准模板库已在本机建立；默认不会向云端发送当前合同。开启云端复核即表示授权本次合同文本发送至 DeepSeek。</p>
        <p v-if="message" class="match-message" role="status">{{ message }}</p>
        <p v-if="match" class="match-engine"><span>执行引擎</span><strong>{{ match.engine.provider }}</strong><small>{{ engineText }}</small></p>
        <div v-if="!match && !isMatching" class="match-empty"><LibraryBig :size="30" /><p>点击“开始匹配”，系统将依据当前已解析合同和标准条款库进行完整性核对。</p></div>
        <ol v-else class="match-list"><li v-for="item in filteredItems" :key="item.code"><span :class="['match-status', statusClass(item.status)]">{{ item.status }}</span><div class="match-main"><strong>{{ item.title }}</strong><p>{{ item.evidence }}</p><small>已识别要素：{{ joinItems(item.presentRequirements, '未确认') }}</small></div><div class="match-gap"><b>建议补充</b><p>{{ joinItems(item.missingRequirements, '未识别出明确缺口') }}</p><small>{{ item.suggestion }}</small></div></li></ol>
        <p v-if="match?.corpusSupport?.status === 'candidate_evidence_only'" class="match-boundary">真实合同证据库：{{ match.corpusSupport.sourceCount }} 份去重来源。{{ match.corpusSupport.message }}</p>
        <p v-else-if="match?.corpusSupport?.status === 'unavailable'" class="match-boundary">真实合同证据库暂不可用；本次继续使用原标准条款库，未使用新增候选证据。</p>
        <p v-if="match" class="match-boundary">{{ match.boundary }}</p>
      </article>
      <aside class="standard-library"><div><p class="section-kicker">Standard Library</p><h3>标准条款库</h3></div><p>当前收录 {{ clauses.length }} 类通用条款主题；来源覆盖数反映已完成本地分析的标准模板。</p><ul><li v-for="clause in clauses" :key="clause.code"><span>{{ clause.requirementCount }}</span><div><strong>{{ clause.title }}</strong><small>{{ clause.category }} · 模板覆盖 {{ clause.sourceCount || 0 }}</small></div></li></ul></aside>
    </section>
  </section>
</template>

<script setup>
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { CircleSlash, Download, FileText, LibraryBig, ScanSearch } from 'lucide-vue-next'
import { isPersistedContract } from '../../shared/contract-content.js'
import { createLatestRequest } from '../utils/latest-request.js'
const props = defineProps({ contract: { type: Object, required: true }, initialMatch: { type: Object, default: null } })
const emit = defineEmits(['match-created'])
const canAnalyze = computed(() => isPersistedContract(props.contract))
const requests = createLatestRequest()
onBeforeUnmount(() => requests.cancel())
const clauses = ref([]), match = ref(props.initialMatch), message = ref(''), isMatching = ref(false), isExporting = ref(false), allowCloudReview = ref(false), statusFilter = ref('全部'), keyword = ref('')
const filteredItems = computed(() => (match.value?.items || []).filter((item) => (statusFilter.value === '全部' || item.status === statusFilter.value) && (!keyword.value || `${item.title} ${item.category} ${item.evidence} ${item.suggestion}`.toLowerCase().includes(keyword.value.toLowerCase()))))
const engineText = computed(() => match.value?.engine?.notice || '执行来源及覆盖情况由后端返回。')
onMounted(loadClauses)
async function loadClauses() { try { const response = await fetch('/api/standard-clauses'); const payload = await response.json(); clauses.value = payload.clauses || [] } catch { clauses.value = [] } }
async function runMatch() { if (!canAnalyze.value) { message.value = '请先上传并成功解析合同。'; return }; const request = requests.begin(); match.value = null; emit('match-created', { parseSnapshotId: props.contract.parseSnapshotId }); isMatching.value = true; message.value = allowCloudReview.value ? '正在运行标准条款库匹配、本地 Qwen 复核及已授权的 DeepSeek 云端复核。' : '正在运行标准条款库匹配，并请求本地 Qwen 审慎复核。'; try { const response = await fetch('/api/contracts/standard-clause-match', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ contract: props.contract, allowCloudReview: allowCloudReview.value }), signal: request.signal }); const payload = await response.json(); if (!response.ok) throw new Error(payload.message || `HTTP ${response.status}`); if (!request.isCurrent()) return; match.value = payload.match; emit('match-created', payload.match); message.value = engineResultMessage(payload.match.engine) } catch (error) { if (!request.isCurrent()) return; message.value = `标准条款匹配失败：${error instanceof Error ? error.message : '未知错误'}` } finally { if (request.isCurrent()) isMatching.value = false } }
async function exportReport() { if (!match.value) return; isExporting.value = true; try { const response = await fetch('/api/contracts/standard-clause-match/export', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ contract: props.contract, match: match.value }) }); if (!response.ok) throw new Error(`HTTP ${response.status}`); downloadBlob(`${safeFileStem(props.contract.sourceFile)}-standard-clause-match-report.docx`, await response.blob()); message.value = '标准条款匹配报告 Word 文件下载已开始。' } catch (error) { message.value = `标准条款匹配报告导出失败：${error instanceof Error ? error.message : '未知错误'}` } finally { isExporting.value = false } }
function joinItems(items, fallback) { return Array.isArray(items) && items.length ? items.join('、') : fallback } function statusClass(status) { return status === '完整' ? 'complete' : status === '部分具备' ? 'partial' : 'missing' } function engineResultMessage(engine = {}) { return engine.notice || ('匹配完成：' + (engine.provider || '标准条款库') + ' / ' + (engine.status || '未记录')) }
</script>

